#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> evens, odds;
        for (int i = 0; i < n; i++) {
            int x; cin >> x;
            if (x % 2 == 0) evens.push_back(x);
            else odds.push_back(x);
        }
        for (size_t i = 0; i < evens.size() && i < odds.size(); i++) {
            if (i > 0) cout << " ";
            cout << evens[i] << " " << odds[i];
        }
        cout << "\n";
    }
    return 0;
}
